## PSFN Design

### New sandbox function: `llm_query_strict`

```typescript
const llm_query_strict = async (
  prompt: string,
  validatePattern?: string,  // regex pattern the output must match
  maxRetries?: number,       // default 3
): Promise<string> => {
  const retries = maxRetries ?? 3;
  let lastResult = '';

  for (let attempt = 0; attempt < retries; attempt++) {
    if (budgetRef.subQueries >= budget.maxSubQueries) {
      return '[Budget exceeded: max sub-queries reached]';
    }
    budgetRef.subQueries++;

    const effectivePrompt = attempt === 0 ? prompt 
      : `${prompt}\n\nYour previous response was invalid (attempt ${attempt}/${retries}). ` +
        `Output must match pattern: ${validatePattern}\n` +
        `Previous output: ${lastResult.slice(0, 200)}`;

    const response = await deps.llmProvider.complete(
      { systemPrompt: 'You are a helpful assistant. Answer concisely.', messages: [{ role: 'user', content: effectivePrompt }] },
      'extraction',
    );
    lastResult = response.content;

    if (!validatePattern) return lastResult;

    try {
      if (new RegExp(validatePattern).test(lastResult)) return lastResult;
    } catch {
      return lastResult; // invalid regex, just return
    }
  }
  return lastResult; // return last attempt even if invalid
};
```

### Also add: `llm_query_json` convenience wrapper

```typescript
const llm_query_json = async (prompt: string, maxRetries?: number): Promise<unknown> => {
  const result = await llm_query_strict(
    prompt + '\n\nRespond with valid JSON only, no markdown.',
    '^\\s*[\\{\\[]',  // starts with { or [
    maxRetries,
  );
  try { return JSON.parse(result); }
  catch { return null; }
};
```

### Changes
1. `src/repl/sandbox.ts` — Add `llm_query_strict` and `llm_query_json` functions, add to context and builtinKeys
2. Budget integration: each retry counts as a sub-query (ties into budget system issue)
3. Evidence tracking: record each attempt as separate evidence item with attempt number

