## PSFN Design

### New module: `src/llm/retry.ts` (~60 lines)

```typescript
export interface RetryConfig {
  maxRetries: number;      // default 3
  baseDelayMs: number;     // default 2000
  retryableErrors?: string[]; // error patterns to retry on
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  config: RetryConfig,
  onRetry?: (attempt: number, delay: number, error: string) => void,
): Promise<T> {
  let lastError: Error;
  for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));
      if (attempt >= config.maxRetries) throw lastError;
      if (!isRetryable(lastError, config.retryableErrors)) throw lastError;
      const delay = config.baseDelayMs * 2 ** attempt;
      onRetry?.(attempt + 1, delay, lastError.message);
      await new Promise(r => setTimeout(r, delay));
    }
  }
  throw lastError!;
}

function isRetryable(err: Error, patterns?: string[]): boolean {
  const msg = err.message.toLowerCase();
  const defaults = ['rate limit', 'timeout', '429', '503', '502', 'econnreset', 'socket hang up'];
  const check = patterns ?? defaults;
  return check.some(p => msg.includes(p.toLowerCase()));
}
```

### Integration points

1. `src/llm/client.ts` — Wrap `stream()` and `complete()` with `withRetry()`. Pass `onRetry` callback that logs via Winston.

2. `src/agent-loop.ts` — `streamWithToolLoop()` wraps the LLM call with retry. Emits `agent.retry.start` / `agent.retry.end` events via EventBus.

3. `src/channels/discord/adapter.ts` — Subscribe to retry events, show "Retrying (2/3)..." status in Discord channel.

4. `src/settings.ts` — Add `retryMaxAttempts`, `retryBaseDelayMs` to EditableSettings. Validation: attempts 0-10, delay 500-30000ms.

5. `src/types.ts` — Add retry config fields to SubstrateConfig (env vars `RETRY_MAX_ATTEMPTS`, `RETRY_BASE_DELAY_MS`).

### Retryable error detection
Default patterns: rate limit (429), server errors (502/503), timeouts, connection resets. User-configurable via settings.

